    if n % i == 0 {
      var j: int := i * i;
      while j <= n
        invariant r == sum_divisors(i - 1)
        invariant j >= i * i
        decreases n - j + 1
      {
        r := r + i;
        if i * i != j {
          r := r + j;
        }
        j := j + i;
      }
    }
    i := i + 1;
  }
  if n % i == 0 {
    r := r + i;
  }
}
